function addBg(slide, dark=false) {
  slide.background = { color: dark ? C.navy : C.lightBg };
  if (dark) {
    slide.addShape(shape.rect, {x:0,y:0,w:W,h:H,fill:{color:C.navy},line:{color:C.navy}});
    slide.addShape(shape.arc, {x:8.3,y:-1.3,w:6.4,h:6.4,adjustPoint:0.55,line:{color:C.blue,transparency:18,width:2},fill:{color:C.navy,transparency:100},rotate:18});
    slide.addShape(shape.arc, {x:9.1,y:-0.55,w:4.8,h:4.8,adjustPoint:0.55,line:{color:C.violet,transparency:40,width:1.3},fill:{color:C.navy,transparency:100},rotate:28});
    slide.addShape(shape.rect, {x:0,y:7.17,w:W,h:.33,fill:{color:C.blue,transparency:75},line:{color:C.blue,transparency:100}});
  } else {
    slide.addShape(shape.rect, {x:0,y:0,w:W,h:H,fill:{color:C.lightBg},line:{color:C.lightBg}});
    slide.addShape(shape.rect, {x:0,y:0,w:.22,h:H,fill:{color:C.blue},line:{color:C.blue}});
    slide.addShape(shape.rect, {x:.22,y:0,w:.08,h:H,fill:{color:C.violet},line:{color:C.violet}});
  }
}
function title(slide, text, sub='') {
  slide.addText(text, {x:.62,y:.34,w:11.7,h:.48,fontFace:'Aptos Display',fontSize:23,bold:true,color:C.ink,margin:0,fit:'shrink'});
  if (sub) slide.addText(sub, {x:.64,y:.88,w:10.9,h:.25,fontSize:8.5,color:C.gray,margin:0,fit:'shrink'});
  slide.addShape(shape.line, {x:.62,y:1.13,w:12.05,h:0,line:{color:C.grid,width:1}});
}
function foot(slide, dark=false) {
  slide.addText('Source: OSSInsight top 20 trending repositories, past 24 hours', {x:.62,y:7.14,w:5.5,h:.18,fontSize:6.8,color:dark?'8EA3BB':C.gray,margin:0});
}
function card(slide,x,y,w,h,opts={}) {
  slide.addShape(shape.roundRect, {x,y,w,h,rectRadius:.08,fill:{color:opts.fill||C.card,transparency:opts.transparency||0},line:{color:opts.line||'E2E8F0',transparency:opts.lineTrans||0,width:opts.lineW||1},shadow:opts.shadow===false?undefined:{type:'outer',color:'203040',opacity:.11,blur:1,angle:45,distance:1}});
}
function stat(slide, x,y,w,num,label,color=C.blue,dark=false) {
  slide.addText(num, {x,y,w,h:.52,fontFace:'Aptos Display',fontSize:26,bold:true,color,margin:0,fit:'shrink'});
  slide.addText(label, {x,y:y+.51,w,h:.32,fontSize:8.5,bold:true,color:dark?C.muted:C.gray,margin:0,fit:'shrink'});
}
function chip(slide,x,y,text,color=C.blue,w=1.2) {
  slide.addShape(shape.roundRect,{x,y,w,h:.28,rectRadius:.08,fill:{color,transparency:86},line:{color,transparency:35,width:.8}});
  slide.addText(text,{x:x+.08,y:y+.06,w:w-.16,h:.12,fontSize:7.2,bold:true,color,align:'center',margin:0,fit:'shrink'});
}
function fmt(n){return n.toLocaleString('en-US');}

